SELECT DISTINCT cs.canonical_smiles, cr_sub.compound_name AS substrate_compound_name, cr_drug.compound_name AS parent_compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name FROM metabolism m JOIN compound_structures cs ON m.substrate_record_id = cs.molregno JOIN compound_records cr_sub ON m.substrate_record_id = cr_sub.molregno JOIN compound_records cr_drug ON m.drug_record_id = cr_drug.molregno WHERE m.enzyme_name = 'CYP2D6' ORDER BY cs.canonical_smiles, cr_sub.compound_name, cr_drug.compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name LIMIT 200
